import{_ as o,o as a,c as t,a3 as c}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Tenant API v1 — Companies","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Companies | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-companies"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Companies | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-companies"}]]},"headers":[],"relativePath":"api/tenant-v1-companies.md","filePath":"api/tenant-v1-companies.md","lastUpdated":1790891496000}'),d={name:"api/tenant-v1-companies.md"};function i(n,e,s,r,p,l){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="tenant-api-v1-—-companies" tabindex="-1">Tenant API v1 — Companies <a class="header-anchor" href="#tenant-api-v1-—-companies" aria-label="Permalink to &quot;Tenant API v1 — Companies&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:companies</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>companies.assign</code> (and not superadmin), list/stats/view/update only include companies where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-companies-stats" tabindex="-1">GET <code>/companies/stats</code> <a class="header-anchor" href="#get-companies-stats" aria-label="Permalink to &quot;GET `/companies/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_companies</code>, <code>my_companies</code>, <code>unassigned</code>, <code>with_email</code>, <code>created_this_week</code>, <code>todays_follow_ups</code>, <code>overdue_follow_ups</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="companies-crud" tabindex="-1">Companies CRUD <a class="header-anchor" href="#companies-crud" aria-label="Permalink to &quot;Companies CRUD&quot;">​</a></h2><h3 id="get-companies" tabindex="-1">GET <code>/companies</code> <a class="header-anchor" href="#get-companies" aria-label="Permalink to &quot;GET `/companies`&quot;">​</a></h3><p>Query: <code>search</code>, <code>industry</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_companies</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>latest_note</code> — most recent note (<code>id</code>, <code>body</code>, <code>author</code>, timestamps) or <code>null</code>, <code>next_follow_up_at</code> (denormalized due timestamp for the earliest <strong>pending</strong> follow-up), and <code>next_follow_up</code> (the full follow-up object, or <code>null</code>). May include <code>contacts_count</code> when counted.</p><h3 id="post-companies" tabindex="-1">POST <code>/companies</code> <a class="header-anchor" href="#post-companies" aria-label="Permalink to &quot;POST `/companies`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>website</code>, <code>industry</code>, <code>address</code>, <code>source</code>, <code>source_meta</code>, <code>assigned_to</code>.</p><h3 id="get-companies-id" tabindex="-1">GET <code>/companies/{id}</code> <a class="header-anchor" href="#get-companies-id" aria-label="Permalink to &quot;GET `/companies/{id}`&quot;">​</a></h3><p>Includes assignee, creator, notes, activities, follow-ups, and linked contacts (when loaded). Embedded <code>notes</code> and <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC). Embedded <code>follow_ups</code> keep product scheduling order (not reversed as a chat feed).</p><h3 id="put-companies-id" tabindex="-1">PUT <code>/companies/{id}</code> <a class="header-anchor" href="#put-companies-id" aria-label="Permalink to &quot;PUT `/companies/{id}`&quot;">​</a></h3><p>Partial update of company fields (including <code>assigned_to</code>).</p><h3 id="delete-companies-id" tabindex="-1">DELETE <code>/companies/{id}</code> <a class="header-anchor" href="#delete-companies-id" aria-label="Permalink to &quot;DELETE `/companies/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>companies.delete</code>.</p><h3 id="post-companies-id-restore" tabindex="-1">POST <code>/companies/{id}/restore</code> <a class="header-anchor" href="#post-companies-id-restore" aria-label="Permalink to &quot;POST `/companies/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted company. Permission: <code>companies.restore</code>.</p><h3 id="delete-companies-id-force" tabindex="-1">DELETE <code>/companies/{id}/force</code> <a class="header-anchor" href="#delete-companies-id-force" aria-label="Permalink to &quot;DELETE `/companies/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted company (must already be trashed). Permission: <code>companies.force.delete</code> (owner by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-companies-id-assign" tabindex="-1">POST <code>/companies/{id}/assign</code> <a class="header-anchor" href="#post-companies-id-assign" aria-label="Permalink to &quot;POST `/companies/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><h3 id="post-companies-id-notes" tabindex="-1">POST <code>/companies/{id}/notes</code> <a class="header-anchor" href="#post-companies-id-notes" aria-label="Permalink to &quot;POST `/companies/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-companies-id-timeline" tabindex="-1">GET <code>/companies/{id}/timeline</code> <a class="header-anchor" href="#get-companies-id-timeline" aria-label="Permalink to &quot;GET `/companies/{id}/timeline`&quot;">​</a></h3><p>Company activity timeline entries.</p><h2 id="follow-ups-1-4-0" tabindex="-1">Follow-ups (1.4.0) <a class="header-anchor" href="#follow-ups-1-4-0" aria-label="Permalink to &quot;Follow-ups (1.4.0)&quot;">​</a></h2><p>Same shape as <a href="/api/tenant-v1-contacts#follow-ups-1-7-0">Contacts follow-ups</a>, scoped by <code>company_id</code>. Permission: <code>companies.update</code> for all follow-up routes.</p><ul><li><code>POST /companies/{id}/follow-ups</code> — <code>{ &quot;title&quot;, &quot;due_at&quot;, &quot;notes&quot;?, &quot;assigned_to&quot;? }</code></li><li><code>PUT /companies/{id}/follow-ups/{followUpId}</code> — partial update; changing <code>due_at</code> reschedules</li><li><code>POST /companies/{id}/follow-ups/{followUpId}/complete</code> — marks completed</li></ul><p>Creating/updating/completing recomputes <code>companies.next_follow_up_at</code> (earliest pending <code>due_at</code>) and, when Calendar is entitled, upserts/clears a <code>company</code> calendar projection. Due/overdue reminders (workspace-local &quot;today&quot;) are sent by the daily <code>crm:send-due-notifications</code> job to the follow-up&#39;s <code>assigned_to</code> (falling back to the company&#39;s assignee).</p><h2 id="import-export-1-4-0" tabindex="-1">Import / Export (1.4.0) <a class="header-anchor" href="#import-export-1-4-0" aria-label="Permalink to &quot;Import / Export (1.4.0)&quot;">​</a></h2><p>Same shape as <a href="/api/tenant-v1-contacts#import-export-1-7-0">Contacts import/export</a>. Permission for export: <code>companies.export</code>. Permission for all import routes: <code>companies.import</code> (+ <code>module:companies</code>). Duplicate mode <code>update</code> also requires <code>companies.update</code>.</p><ul><li><code>GET /companies/export?format=csv|xlsx</code> — id, name, email, phone, website, industry, source, assignee, creator, contacts count, next follow-up, created at</li><li><code>GET /companies/import/template?format=csv|xlsx</code></li><li><code>GET/POST /companies/imports</code>, <code>GET/PUT /companies/imports/{uuid}</code>, <code>PUT /companies/imports/{uuid}/options</code>, <code>POST /companies/imports/{uuid}/preview</code>, <code>POST /companies/imports/{uuid}/run</code></li><li><code>GET /companies/imports/{uuid}/file</code>, <code>/failed-records</code>, <code>/error-report</code></li></ul><p>Mappable fields: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>website</code>, <code>industry</code>, <code>source</code>, <code>assigned_to</code>. Options body: <code>{ &quot;unique_fields&quot;: [&quot;email&quot;,&quot;phone&quot;], &quot;duplicate_mode&quot;: &quot;skip&quot;|&quot;update&quot;|&quot;keep&quot; }</code> — <strong>no <code>assignment_mode</code></strong> (no equal-distribute; <code>assigned_to</code> column or manual-create default only). Queued via <code>ProcessCompanyImportJob</code> on the <code>imports</code> queue.</p><h2 id="billing-summary-statement" tabindex="-1">Billing summary &amp; statement <a class="header-anchor" href="#billing-summary-statement" aria-label="Permalink to &quot;Billing summary &amp; statement&quot;">​</a></h2><p>Same shape as <a href="/api/tenant-v1-contacts#billing-summary--statement">Contacts billing summary &amp; statement</a>, scoped by <code>company_id</code>:</p><ul><li><code>GET /companies/{id}/billing-summary</code></li><li><code>GET /companies/{id}/statement?from=&amp;to=</code> (includes <code>opening_balance</code> + <code>balance_due</code>)</li><li><code>GET /companies/{id}/statement.pdf?from=&amp;to=</code></li></ul><h2 id="contact-linkage" tabindex="-1">Contact linkage <a class="header-anchor" href="#contact-linkage" aria-label="Permalink to &quot;Contact linkage&quot;">​</a></h2><p>Contact create/update (see <a href="/api/tenant-v1-contacts">tenant-v1-contacts.md</a>) accept optional <code>company_id</code>. When set, the contact’s legacy <code>company</code> string is synced to the linked Company name. List/detail contact payloads may include <code>company_id</code> and <code>linked_company</code> (<code>id</code>, <code>uuid</code>, <code>name</code>).</p>',44)])])}const h=o(d,[["render",i]]);export{u as __pageData,h as default};
